import {createRoot} from 'react-dom/client';
import {StrictMode,useEffect,useState} from 'react';
import {RoomScene,type RoomSceneRoom} from '../../src/hearthside/RoomScene.tsx';
import {captureRoomFurniture,type FurniturePlacement,type FurnitureMove} from '../../src/hearthside/roomFurniture.ts';
import type {ThemeId} from '../../src/theme/scenes.ts';
function Proof(){const [theme,setTheme]=useState<ThemeId>('classic'),[room,setRoom]=useState<RoomSceneRoom>('common'),[member,setMember]=useState('alice'),[household,setHousehold]=useState('one'),[state,setState]=useState<FurniturePlacement[]>([]),[point,setPoint]=useState({x:.7,y:.65}),[message,setMessage]=useState('');const scope=household+'/'+member;
 useEffect(()=>{let live=true;const read=async()=>{const r=await fetch('/__furniture/state?household='+household);const rows=await r.json();if(live)setState(old=>JSON.stringify(old)===JSON.stringify(rows)?old:rows);};void read();const timer=setInterval(()=>void read(),150);return()=>{live=false;clearInterval(timer);};},[scope]);
 async function save(move:FurnitureMove){const response=await fetch('/__furniture/move?household='+household,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(move)});const result=await response.json();if(!response.ok)throw Error(result.code);setState(result);}
 return <main><div className="proof-controls"><label>Theme <select aria-label="Test theme" value={theme} onChange={e=>setTheme(e.target.value as ThemeId)}>{['classic','taylor','newfoundland'].map(v=><option key={v}>{v}</option>)}</select></label><label>Room <select aria-label="Test room" value={room} onChange={e=>setRoom(e.target.value as RoomSceneRoom)}>{['common','studio','conservatory','theatre'].map(v=><option key={v}>{v}</option>)}</select></label><label>Member <select aria-label="Test member" value={member} onChange={e=>setMember(e.target.value)}><option>alice</option><option>bob</option></select></label><label>Household <select aria-label="Test household" value={household} onChange={e=>{setState([]);setHousehold(e.target.value);}}><option>one</option><option>two</option></select></label><button onClick={()=>setMessage('Global action works')}>Global action</button><output>{message}</output></div><RoomScene key={scope} scopeKey={scope} room={room} theme={theme} furniture={captureRoomFurniture(room,state)} onArrangeFurniture={save} onNavigate={setRoom} onArrange={(_id,x,y)=>setPoint({x,y})} objects={[{id:'note-1',kind:'note',label:'A thought for tonight',surfaceLabel:'A kind thought',onActivate:()=>setMessage('Note opened')},{id:'piece-1',kind:'piece',label:'Our painted piece',surfaceLabel:'Painted piece',...point,onActivate:()=>setMessage('Piece opened')}]} /><output data-state>{JSON.stringify(state)}</output></main>;
}
createRoot(document.getElementById('root')!).render(<StrictMode><Proof/></StrictMode>);
